10	/**
11	 * Shared logic for building the core hook action message while allowing the
12	 * caller to control how each scope and its path are rendered (e.g., bolding or
13	 * dimming).
14	 */
15	export function renderHookActionFeedback(
16	  result: HookActionResult,
17	  formatScope: (label: string, path: string) => string,
18	): string {
19	  const { hookName, action, status, error } = result;
20	
21	  if (status === 'error') {
22	    return (
23	      error ||
24	      `An error occurred while attempting to ${action} hook "${hookName}".`
25	    );
26	  }
27	
28	  if (status === 'no-op') {
29	    return `Hook "${hookName}" is already ${action === 'enable' ? 'enabled' : 'disabled'}.`;
30	  }
31	
32	  const isEnable = action === 'enable';
33	  const actionVerb = isEnable ? 'enabled' : 'disabled';
34	  const preposition = isEnable
35	    ? 'by removing it from the disabled list in'
36	    : 'by adding it to the disabled list in';
37	
38	  const formatScopeItem = (s: { scope: SettingScope; path: string }) => {
39	    const label =
40	      s.scope === SettingScope.Workspace ? 'workspace' : s.scope.toLowerCase();
41	    return formatScope(label, s.path);
42	  };
43	
44	  const totalAffectedScopes = [
45	    ...result.modifiedScopes,
46	    ...result.alreadyInStateScopes,
47	  ];
48	
49	  if (totalAffectedScopes.length === 0) {
50	    // This case should ideally not happen, but as a safeguard, return a generic message.
51	    return `Hook "${hookName}" ${actionVerb}.`;
52	  }
53	
54	  if (totalAffectedScopes.length === 2) {
55	    const s1 = formatScopeItem(totalAffectedScopes[0]);
56	    const s2 = formatScopeItem(totalAffectedScopes[1]);
57	
58	    if (isEnable) {
59	      return `Hook "${hookName}" ${actionVerb} ${preposition} ${s1} and ${s2} settings.`;
60	    } else {
61	      return `Hook "${hookName}" is now disabled in both ${s1} and ${s2} settings.`;
62	    }
63	  }
64	
65	  const s = formatScopeItem(totalAffectedScopes[0]);
66	  return `Hook "${hookName}" ${actionVerb} ${preposition} ${s} settings.`;
67	}
