15	export type HookActionStatus = 'success' | 'no-op' | 'error';
16	
17	/**
18	 * Metadata representing the result of a hook settings operation.
19	 */
20	export interface HookActionResult {
21	  status: HookActionStatus;
22	  hookName: string;
23	  action: 'enable' | 'disable';
24	  /** Scopes where the hook's state was actually changed. */
25	  modifiedScopes: ModifiedScope[];
26	  /** Scopes where the hook was already in the desired state. */
27	  alreadyInStateScopes: ModifiedScope[];
28	  /** Error message if status is 'error'. */
29	  error?: string;
30	}
