32	/**
33	 * Enables a hook by removing it from all writable disabled lists (User and Workspace).
34	 */
35	export function enableHook(
36	  settings: LoadedSettings,
37	  hookName: string,
38	): HookActionResult {
39	  const writableScopes = [SettingScope.Workspace, SettingScope.User];
40	  const foundInDisabledScopes: ModifiedScope[] = [];
41	  const alreadyEnabledScopes: ModifiedScope[] = [];
42	
43	  for (const scope of writableScopes) {
44	    if (isLoadableSettingScope(scope)) {
45	      const scopePath = settings.forScope(scope).path;
46	      const scopeDisabled =
47	        settings.forScope(scope).settings.hooksConfig?.disabled;
48	      if (scopeDisabled?.includes(hookName)) {
49	        foundInDisabledScopes.push({ scope, path: scopePath });
50	      } else {
51	        alreadyEnabledScopes.push({ scope, path: scopePath });
52	      }
53	    }
54	  }
55	
56	  if (foundInDisabledScopes.length === 0) {
57	    return {
58	      status: 'no-op',
59	      hookName,
60	      action: 'enable',
61	      modifiedScopes: [],
62	      alreadyInStateScopes: alreadyEnabledScopes,
63	    };
64	  }
65	
66	  const modifiedScopes: ModifiedScope[] = [];
67	  try {
68	    for (const { scope, path } of foundInDisabledScopes) {
69	      if (isLoadableSettingScope(scope)) {
70	        const currentScopeDisabled =
71	          settings.forScope(scope).settings.hooksConfig?.disabled ?? [];
72	        const newDisabled = currentScopeDisabled.filter(
73	          (name) => name !== hookName,
74	        );
75	        settings.setValue(scope, 'hooksConfig.disabled', newDisabled);
76	        modifiedScopes.push({ scope, path });
77	      }
78	    }
79	  } catch (error) {
80	    return {
81	      status: 'error',
82	      hookName,
83	      action: 'enable',
84	      modifiedScopes,
85	      alreadyInStateScopes: alreadyEnabledScopes,
86	      error: `Failed to enable hook: ${getErrorMessage(error)}`,
87	    };
88	  }
89	
90	  return {
91	    status: 'success',
92	    hookName,
93	    action: 'enable',
94	    modifiedScopes,
95	    alreadyInStateScopes: alreadyEnabledScopes,
96	  };
97	}
