99	/**
100	 * Disables a hook by adding it to the disabled list in the specified scope.
101	 */
102	export function disableHook(
103	  settings: LoadedSettings,
104	  hookName: string,
105	  scope: SettingScope,
106	): HookActionResult {
107	  if (!isLoadableSettingScope(scope)) {
108	    return {
109	      status: 'error',
110	      hookName,
111	      action: 'disable',
112	      modifiedScopes: [],
113	      alreadyInStateScopes: [],
114	      error: `Invalid settings scope: ${scope}`,
115	    };
116	  }
117	
118	  const scopePath = settings.forScope(scope).path;
119	  const currentScopeDisabled =
120	    settings.forScope(scope).settings.hooksConfig?.disabled ?? [];
121	
122	  if (currentScopeDisabled.includes(hookName)) {
123	    return {
124	      status: 'no-op',
125	      hookName,
126	      action: 'disable',
127	      modifiedScopes: [],
128	      alreadyInStateScopes: [{ scope, path: scopePath }],
129	    };
130	  }
131	
132	  // Check if it's already disabled in the other writable scope
133	  const otherScope =
134	    scope === SettingScope.Workspace
135	      ? SettingScope.User
136	      : SettingScope.Workspace;
137	  const alreadyDisabledInOther: ModifiedScope[] = [];
138	
139	  if (isLoadableSettingScope(otherScope)) {
140	    const otherScopeDisabled =
141	      settings.forScope(otherScope).settings.hooksConfig?.disabled;
142	    if (otherScopeDisabled?.includes(hookName)) {
143	      alreadyDisabledInOther.push({
144	        scope: otherScope,
145	        path: settings.forScope(otherScope).path,
146	      });
147	    }
148	  }
149	
150	  const newDisabled = [...currentScopeDisabled, hookName];
151	  settings.setValue(scope, 'hooksConfig.disabled', newDisabled);
152	
153	  return {
154	    status: 'success',
155	    hookName,
156	    action: 'disable',
157	    modifiedScopes: [{ scope, path: scopePath }],
158	    alreadyInStateScopes: alreadyDisabledInOther,
159	  };
160	}
