31	/**
32	 * Enables an agent by ensuring it is enabled in any writable scope (User and Workspace).
33	 * It sets `agents.overrides.<agentName>.enabled` to `true`.
34	 */
35	export function enableAgent(
36	  settings: LoadedSettings,
37	  agentName: string,
38	): AgentActionResult {
39	  const writableScopes = [SettingScope.Workspace, SettingScope.User];
40	  const foundInDisabledScopes: ModifiedScope[] = [];
41	  const alreadyEnabledScopes: ModifiedScope[] = [];
42	
43	  for (const scope of writableScopes) {
44	    if (isLoadableSettingScope(scope)) {
45	      const scopePath = settings.forScope(scope).path;
46	      const agentOverrides =
47	        settings.forScope(scope).settings.agents?.overrides;
48	      const isEnabled = agentOverrides?.[agentName]?.enabled === true;
49	
50	      if (!isEnabled) {
51	        foundInDisabledScopes.push({ scope, path: scopePath });
52	      } else {
53	        alreadyEnabledScopes.push({ scope, path: scopePath });
54	      }
55	    }
56	  }
57	
58	  if (foundInDisabledScopes.length === 0) {
59	    return {
60	      status: 'no-op',
61	      agentName,
62	      action: 'enable',
63	      modifiedScopes: [],
64	      alreadyInStateScopes: alreadyEnabledScopes,
65	    };
66	  }
67	
68	  const modifiedScopes: ModifiedScope[] = [];
69	  for (const { scope, path } of foundInDisabledScopes) {
70	    if (isLoadableSettingScope(scope)) {
71	      // Explicitly enable it.
72	      settings.setValue(scope, `agents.overrides.${agentName}.enabled`, true);
